// Software acceptance only: generated bytes, no disk capture and no audio hardware.
#include "../../src/spatial_transport/mat_live_session.h"
#include "../../src/spatial_audio/native_mat_assembler.h"
#include "../../third-party/moonlight-common-c/src/MatLivePlayback.h"
#include <iostream>
static int frames=0,ends=0;
static int Cycle(void*,const uint8_t*,int n,uint64_t e,uint64_t d,uint64_t i,uint64_t pts){return n==61440 && e==123 && d==7 && i==unsigned(frames++) && pts==i*960;}
static int End(void*,uint64_t n){++ends;return n==unsigned(frames);}
static void Check(bool b){if(!b)throw std::runtime_error("test assertion");}
static std::vector<uint8_t> Carrier(){std::vector<uint8_t> b(61440);memcpy(b.data(),"\x72\xf8\x1f\x4e\x16\x00\x02\x00",8);return b;}
struct TestSource final:spatial_audio::EncodedAudioSource {
 int n=0;bool fail=false,stopped=false;
 spatial_audio::Descriptor descriptor()const override{return {};}
 bool start()override{return true;}
 spatial_audio::Read read(spatial_audio::Frame& f)override{
  if(fail)return spatial_audio::Read::failed;if(n==8)return spatial_audio::Read::ended;
  f={};f.bytes=Carrier();f.sequence=n;f.sample_start=n++*960;return spatial_audio::Read::frame;
 }
 void stop()override{stopped=true;}
 spatial_audio::State state()const override{return spatial_audio::State::running;}
 std::string error()const override{return "test";}
};
int main(){try{
 uint8_t key[16]={};LI_MAT_PLAYBACK_CALLBACKS cb{};cb.cycle=Cycle;cb.end=End;LI_MAT_LIVE_PROFILE profile{123,7};
 auto receiver=MatLivePlaybackOpen(&profile,key,&cb);Check(receiver);
 spatial_transport::LiveSession session;session.profile=profile;session.source=std::make_unique<TestSource>();uint64_t packet=0;
 auto emitted=[&](const uint8_t* p,size_t n){if(packet++>=4)Check(MatLivePlaybackPush(receiver,p,n)>=0);};
 auto wait=[](auto delay){if(delay>std::chrono::nanoseconds(0))std::this_thread::sleep_for(delay);};
 Check(spatial_transport::live_session(session,key,16,emitted,wait,[]{return false;})==8 && frames==8 && ends==1 && packet==488);
 Check(static_cast<TestSource*>(session.source.get())->stopped);MatLivePlaybackClose(receiver);
 bool caught=false;try{spatial_transport::live_session(session,key,16,emitted,wait,[]{return false;});}catch(const std::runtime_error&){caught=true;}Check(caught);
 session.started=false;static_cast<TestSource*>(session.source.get())->fail=true;packet=0;ends=0;
 caught=false;try{spatial_transport::live_session(session,key,16,[&](auto*,auto){++packet;},wait,[]{return false;});}catch(const std::runtime_error&){caught=true;}Check(caught);
 Check(packet==4 && ends==0); // Only SYNC; a failed source must never synthesize an END.
 // A zero-cycle probe must distinguish idle, empty output, wrong contract and
 // non-MAT bytes. No sample file or native process is involved in these tests.
 {
  mat_capture::Assembler a;auto generated=Carrier();unsigned emitted=0;
  Check(a.observations().records==0 && a.startup_skipped()==0);
  EncodedRecord r{0x42595445,0,0,1,42,480,30720,0,1,S_OK,0,0};
  auto sink=[&](auto&,auto){++emitted;};a.push(r,nullptr,sink);
  Check(a.startup_skipped()==1 && a.observations().empty==1 && a.observations().records==1);
  r={0x42595445,1,1,2,42,256,1,1,1,S_FALSE,0,0};a.push(r,generated.data(),sink);
  Check(a.startup_skipped()==2 && a.observations().wrong_result==1 && a.observations().wrong_frames==1 && a.observations().wrong_bytes==2);
  r={0x42595445,30720,2,3,42,480,30720,30720,1,S_OK,0,0};
  a.push(r,generated.data()+30720,sink);
  Check(a.startup_skipped()==3 && a.observations().non_mat==3 && !emitted);
  r.sequence=3;r.qpc=4;a.push(r,generated.data(),sink);
  Check(a.partial() && a.observations().accepted_halves==1 && a.startup_skipped()==3 && !emitted);
  r.sequence=4;r.qpc=5;a.push(r,generated.data()+30720,sink);
  Check(!a.partial() && emitted==1 && a.observations().records==5 && a.observations().accepted_halves==2);
 }
 mat_capture::Descriptor identity{mat_capture::test_source,1,2,3,4,5,6,7},decoded;uint8_t descriptor[80];mat_capture::encode_descriptor(descriptor,identity);Check(!mat_capture::decode_descriptor(descriptor,decoded));
 identity.kind=mat_capture::native_source;mat_capture::encode_descriptor(descriptor,identity);Check(mat_capture::decode_descriptor(descriptor,decoded));descriptor[20]=1;Check(!mat_capture::decode_descriptor(descriptor,decoded));
 auto bytes=Carrier();mat_capture::Assembler assembler;unsigned cycles=0;
 EncodedRecord record{0x42595445,30720,0,10,42,480,30720,30720,1,S_OK,0,0};
 assembler.push(record,bytes.data(),[&](auto&,auto){++cycles;});record.sequence=1;record.qpc=20;
 assembler.push(record,bytes.data()+30720,[&](auto& b,auto qpc){Check(qpc==10 && std::equal(b.begin(),b.end(),bytes.begin()));++cycles;});Check(cycles==1);
 record.sequence=3;bool failed=false;try{assembler.push(record,bytes.data(),[](auto&,auto){});}catch(...){failed=true;}Check(failed);
 for(unsigned test=0;test<4;test++){
  mat_capture::Assembler a;record={0x42595445,30720,0,10,42,480,30720,30720,1,S_OK,0,0};a.push(record,bytes.data(),[](auto&,auto){});
  record.sequence=1;record.qpc=20;if(test==0)record.encoder=43;if(test==1)record.result=E_FAIL;if(test==2)record.bytes=0;if(test==3)record.qpc=9;
  failed=false;try{a.push(record,bytes.data()+30720,[](auto&,auto){});}catch(...){failed=true;}Check(failed);
 }
 std::cout<<"PASS host live sender/source lifecycle, exact-cycle assembler and fail-closed native descriptor\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
